/**
 * Builds `src/generated/icons.ts`: one typed component per catalog icon.
 *
 *   node scripts/generate.ts           write the file
 *   node scripts/generate.ts --check   fail if the file is out of date
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { iconComponentName, iconExportName, icons } from "@0xdolan/deq-icons";

const OUT = fileURLToPath(new URL("../src/generated/icons.ts", import.meta.url));

export function generate(): string {
  const ids = Object.keys(icons);
  const lines = [
    "// Generated by scripts/generate.ts from @0xdolan/deq-icons.",
    "// Do not edit: run `pnpm --filter @0xdolan/deq-react generate`.",
    `import { ${ids.map(iconExportName).join(", ")} } from "@0xdolan/deq-icons";`,
    "",
    'import { createDeqIcon } from "../create.js";',
    "",
  ];
  for (const id of ids) {
    const c = iconComponentName(id);
    lines.push(
      `/** ${icons[id]?.title ?? id} (\`${id}\`). */`,
      `export const ${c} = /*#__PURE__*/ createDeqIcon(${iconExportName(id)}, "${c}");`,
    );
  }
  return `${lines.join("\n")}\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = generate();
  if (!process.argv.includes("--check")) writeFileSync(OUT, text);
  else if (readFileSync(OUT, "utf8") !== text) {
    console.error(`${OUT} is out of date: run \`pnpm --filter @0xdolan/deq-react generate\``);
    process.exit(1);
  }
}
